class StandardSounds:
    """Звуки для строя: Стандартный"""

    _NOTE_NAME_MAP = {
        "E2": "E2",
        "A2": "A2",
        "D3": "D3",
        "G3": "G3",
        "B3": "B3",
        "E4": "E4",
    }

    @staticmethod
    def get_sound_data(note_name: str) -> Optional[bytes]:
        safe_name = StandardSounds._NOTE_NAME_MAP.get(note_name)
        if safe_name:
            var_name = f"_{safe_name}_BASE64"
            if var_name in globals():
                return base64.b64decode(globals()[var_name])
        return None

    @staticmethod
    def get_sound(note_name: str):
        if not KIVY_AVAILABLE:
            return None
        data = StandardSounds.get_sound_data(note_name)
        if data:
            try:
                fd, path = tempfile.mkstemp(suffix=".wav")
                os.close(fd)
                with open(path, "wb") as f:
                    f.write(data)
                sound = SoundLoader.load(path)
                # Отложенное удаление, чтобы Windows и Android успели прочитать файл
                def _cleanup(dt):
                    try:
                        if os.path.exists(path):
                            os.unlink(path)
                    except Exception:
                        pass
                Clock.schedule_once(_cleanup, 5.0)
                return sound
            except Exception:
                return None
        return None

    @staticmethod
    def get_all_notes() -> list:
        return list(NOTES_METADATA.keys())

TUNING_NAME = "Стандартный"
TUNING_ID = "standard"
__all__ = ["StandardSounds", "NOTES_METADATA"]